-- SPDX-License-Identifier: MIT OR Apache-2.0
CREATE TABLE truss.runtime_migration_receipt (
 attempt_id uuid PRIMARY KEY, request_bytes bytea NOT NULL,
 request_sha256 text NOT NULL CHECK(request_sha256=encode(sha256(request_bytes),'hex')),
 source_sha256 text NOT NULL, target_sha256 text NOT NULL,
 target_release text NOT NULL, target_layout_profile jsonb NOT NULL,target_configuration jsonb NOT NULL,
 recipe_sha256 text NOT NULL, recipe_bytes bytea NOT NULL,
 source_inventory_bytes bytea NOT NULL,target_inventory_bytes bytea NOT NULL,
 step_evidence_bytes bytea NOT NULL,preservation_bytes bytea NOT NULL,
 writer_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION truss.runtime_migration_immutable() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$ BEGIN
 RAISE EXCEPTION 'migration receipts are immutable' USING ERRCODE='55000'; END; $$;
CREATE TRIGGER runtime_migration_immutable BEFORE UPDATE OR DELETE OR TRUNCATE
 ON truss.runtime_migration_receipt FOR EACH STATEMENT EXECUTE FUNCTION truss.runtime_migration_immutable();
ALTER TABLE truss.runtime_migration_receipt ENABLE ALWAYS TRIGGER runtime_migration_immutable;
CREATE OR REPLACE FUNCTION truss.runtime_current_installation() RETURNS SETOF truss.catalog_runtime_installation
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,pg_temp AS $$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE; transition record;
BEGIN
 SELECT * INTO STRICT installation FROM truss.catalog_runtime_installation;
 SELECT * INTO transition FROM truss.runtime_migration_receipt ORDER BY writer_xid DESC LIMIT 1;
 IF FOUND THEN
  installation.release_id:=transition.target_release;
  installation.release_sha256:=transition.target_sha256;
  installation.layout_profile:=transition.target_layout_profile;
  installation.preparation_configuration:=transition.target_configuration;
 END IF;
 RETURN NEXT installation;
END; $$;
REVOKE ALL ON FUNCTION truss.runtime_current_installation(),truss.runtime_migration_immutable() FROM PUBLIC;
CREATE OR REPLACE FUNCTION truss.catalog_accept_with_keys(input_bytes bytea, documents_bytes bytea, declarations_bytes bytea, source_bytes bytea, origin_bytes bytea, request_key text, key_receipts bytea, preview_mode boolean, expected_revision integer, expected_documents bytea)
 RETURNS TABLE(revision text, registration_id text, report_bytes bytea, replayed boolean, unchanged boolean, actor_name text, violations_bytes bytea)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE actor oid; installation truss.catalog_runtime_installation%ROWTYPE;
 request truss.catalog_registration_request%ROWTYPE; existing truss.catalog_registration_request%ROWTYPE;
 alias_request truss.catalog_unchanged_request%ROWTYPE;
 expected jsonb; prior_expected jsonb; origin bytea; original_report bytea; table_name text; columns text; assignments text;identity_column text;conflict_columns text; rows jsonb; raw bytea; total bigint:=0; request_count bigint;
 expected_docs jsonb; expected_doc jsonb;
 prior_revision int;new_revision int;type_start int;property_start int;relationship_start int;component_index int:=0;component_limit int;compact boolean;violations bytea;key_candidates jsonb;verified_keys jsonb;
BEGIN
 IF preview_mode IS NULL THEN RAISE EXCEPTION 'explicit catalog mode required' USING ERRCODE='22023';END IF;
 compact:=(convert_from(input_bytes,'UTF8')::jsonb)->>'interfaceVersion'='truss-acceptance-input/0.2.0';
 IF compact AND declarations_bytes<>''::bytea THEN RAISE EXCEPTION 'source-only catalog request required' USING ERRCODE='22023';END IF;
 actor:=truss.catalog_actor();
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id<>'truss-catalog-runtime/0.73-candidate' OR request_key IS NULL OR octet_length(request_key) NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'selected catalog release and request key required' USING ERRCODE='22023'; END IF;
 FOREACH raw IN ARRAY ARRAY[input_bytes,documents_bytes,declarations_bytes,source_bytes,origin_bytes] LOOP
  component_index:=component_index+1;
  component_limit:=CASE WHEN component_index=5 THEN 1048576 WHEN component_index=4 THEN 4194304 ELSE 16777216 END;
  IF raw IS NULL OR NOT (compact AND component_index=3 AND octet_length(raw)=0) AND octet_length(raw) NOT BETWEEN 1 AND component_limit THEN
   RAISE EXCEPTION 'catalog input byte limit exceeded' USING ERRCODE='22023'; END IF;
  total:=total+octet_length(raw);
 END LOOP;
 IF total>16777216 OR jsonb_typeof(convert_from(origin_bytes,'UTF8')::jsonb) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'bounded catalog request required' USING ERRCODE='22023'; END IF;
 IF expected_revision IS NOT NULL AND expected_revision NOT BETWEEN -1 AND 2147483647
  OR expected_documents IS NULL OR octet_length(expected_documents) NOT BETWEEN 2 AND 1048576 THEN
  RAISE EXCEPTION 'bounded catalog source expectations required' USING ERRCODE='22023';END IF;
 -- The private host's immutable semantic-parameter lane excludes SQL NULL.
 -- Normalize its -1 sentinel immediately so custody and replay remain byte-for-byte
 -- identical to historical no-CAS requests.
 IF expected_revision=-1 THEN expected_revision:=NULL;END IF;
 expected_docs:=convert_from(expected_documents,'UTF8')::jsonb;
 IF jsonb_typeof(expected_docs) IS DISTINCT FROM 'array' OR jsonb_array_length(expected_docs)>512 THEN
  RAISE EXCEPTION 'catalog source expectations required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(expected_docs)>0 THEN
  IF jsonb_array_length(expected_docs)<>jsonb_array_length(convert_from(documents_bytes,'UTF8')::jsonb)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e
    WHERE jsonb_typeof(e.value) IS DISTINCT FROM 'object'
     OR (SELECT count(*) FROM jsonb_object_keys(e.value))<>2
     OR jsonb_typeof(e.value->'documentId') IS DISTINCT FROM 'string'
     OR octet_length(e.value->>'documentId') NOT BETWEEN 1 AND 4096
     OR jsonb_typeof(e.value->'sourceCatalogRevision') IS DISTINCT FROM 'number'
     OR (e.value->>'sourceCatalogRevision') !~ '^(0|[1-9][0-9]*)$'
     OR (e.value->>'sourceCatalogRevision')::numeric>2147483647)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e GROUP BY e.value->>'documentId' HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d GROUP BY d.value->>'documentId' HAVING count(*)<>1)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d
    WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected_docs) e WHERE e.value->>'documentId'=d.value->>'documentId')) THEN
   RAISE EXCEPTION 'exact submitted document expectation set required' USING ERRCODE='22023';END IF;
 END IF;
 IF compact THEN declarations_bytes:=truss.runtime_owned_catalog_declarations(documents_bytes);END IF;
 -- Bound concurrency without an automatic retry loop.
 SELECT rev INTO STRICT prior_revision FROM truss.schema_head WHERE id=1 FOR UPDATE NOWAIT;
 prior_expected:=truss.catalog_all_expected_records();
 SELECT count(*) INTO request_count FROM (
  SELECT 1 FROM truss.catalog_registration_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key
  UNION ALL SELECT 1 FROM truss.catalog_unchanged_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key) requests;
 IF request_count>1 THEN RAISE EXCEPTION 'unambiguous catalog request required' USING ERRCODE='55000'; END IF;
 SELECT * INTO existing FROM truss.catalog_registration_request r WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key;
 IF FOUND THEN
  IF existing.input_bytes IS DISTINCT FROM input_bytes OR existing.expected_revision IS DISTINCT FROM expected_revision OR existing.expected_documents IS DISTINCT FROM expected_documents OR (CASE WHEN octet_length(existing.document_bytes)=0 THEN
    convert_from(truss.runtime_owned_request_documents(existing),'UTF8')::jsonb IS DISTINCT FROM convert_from(documents_bytes,'UTF8')::jsonb
   ELSE existing.document_bytes IS DISTINCT FROM documents_bytes OR existing.declaration_bytes IS DISTINCT FROM declarations_bytes END) OR existing.origin_bytes IS DISTINCT FROM origin_bytes THEN
   RAISE EXCEPTION 'request key reused with different registration input' USING ERRCODE='P1001'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,true,false,existing.actor_name,NULL::bytea FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 SELECT * INTO alias_request FROM truss.catalog_unchanged_request r
  WHERE r.installation_id=installation.installation_id AND r.actor_oid=actor AND r.request_key=catalog_accept_with_keys.request_key;
 IF FOUND THEN
  SELECT * INTO STRICT existing FROM truss.catalog_registration_request r WHERE r.registration_id=alias_request.registration_id;
  IF existing.input_bytes IS DISTINCT FROM input_bytes OR (CASE WHEN octet_length(existing.document_bytes)=0 THEN
    convert_from(truss.runtime_owned_request_documents(existing),'UTF8')::jsonb IS DISTINCT FROM convert_from(documents_bytes,'UTF8')::jsonb
   ELSE existing.document_bytes IS DISTINCT FROM documents_bytes OR existing.declaration_bytes IS DISTINCT FROM declarations_bytes END)
   OR alias_request.origin_bytes IS DISTINCT FROM origin_bytes OR alias_request.expected_revision IS DISTINCT FROM expected_revision
   OR alias_request.expected_documents IS DISTINCT FROM expected_documents THEN
   RAISE EXCEPTION 'request key reused with different registration input' USING ERRCODE='P1001'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,true,true,alias_request.actor_name,NULL::bytea
   FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 -- Source and optional global CAS checks happen only after exact authorized
 -- replay resolution, under the same schema-head serialization lock.
 IF expected_revision IS NOT NULL AND prior_revision IS DISTINCT FROM expected_revision THEN
  RAISE EXCEPTION 'expected catalog revision changed' USING ERRCODE='P1011';END IF;
 IF jsonb_array_length(expected_docs)>0 THEN
  FOR expected_doc IN SELECT value FROM jsonb_array_elements(expected_docs) LOOP
   IF coalesce((SELECT max(rev) FROM truss.schema_doc WHERE doc_id=expected_doc->>'documentId'),0)
     IS DISTINCT FROM (expected_doc->>'sourceCatalogRevision')::int THEN
    RAISE EXCEPTION 'expected document source revision changed' USING ERRCODE='P1011';END IF;
  END LOOP;
 END IF;
 -- Ordinary registration keeps one validation summary per original document.
 -- Semantic source/declaration checks and atomic publication remain native.
 IF (convert_from(source_bytes,'UTF8')::jsonb)->>'sourceFormat' ='truss-registration-summary/2.0' THEN
  DECLARE
   summary jsonb:=convert_from(source_bytes,'UTF8')::jsonb;
   original_input jsonb:=convert_from(input_bytes,'UTF8')::jsonb;
   original_docs jsonb:=convert_from(documents_bytes,'UTF8')::jsonb;
   doc jsonb; validation jsonb; selected_doc jsonb; ddd_profile jsonb; ddd_validation jsonb; ddd_known boolean; doc_index int:=0;
  BEGIN
   IF (SELECT count(*) FROM jsonb_object_keys(summary))<>3
    OR jsonb_typeof(summary->'umf') IS DISTINCT FROM 'array'
    OR jsonb_typeof(summary->'documentValidations') IS DISTINCT FROM 'array'
    OR jsonb_array_length(summary->'documentValidations')<>jsonb_array_length(original_docs)
    OR original_input->'binding' IS DISTINCT FROM '{"state":"absent"}'::jsonb
    OR original_input->'transforms' IS DISTINCT FROM '[]'::jsonb THEN
    RAISE EXCEPTION 'original native registration summary required' USING ERRCODE='22023';END IF;
   FOR doc IN SELECT value FROM jsonb_array_elements(original_docs) LOOP
    validation:=summary->'documentValidations'->doc_index;
    selected_doc:=original_input->'documents'->doc_index;
    ddd_known:=((doc->>'originalText')::jsonb->'vocabularies'->'umf.ddd'->>'version')='0.1.0';
    ddd_profile:=validation->'dddProfile';ddd_validation:=validation->'dddValidation';
    IF (SELECT count(*) FROM jsonb_object_keys(validation))<>
      (CASE WHEN ddd_known THEN 5 ELSE 3 END)
      OR validation->>'documentId' IS DISTINCT FROM doc->>'documentId'
      OR validation->>'contentSha256' IS DISTINCT FROM selected_doc->'artifact'->>'sha256'
      OR selected_doc->'ingress' IS DISTINCT FROM '{"kind":"native"}'::jsonb
      OR validation->'validation' IS DISTINCT FROM doc->'validation'->'sourceValidation'
      OR validation->'validation'->'valid' IS DISTINCT FROM 'true'::jsonb
      OR jsonb_typeof(validation->'validation'->'complete') IS DISTINCT FROM 'boolean'
      OR jsonb_typeof(validation->'validation'->'diagnostics') IS DISTINCT FROM 'array'
      OR ddd_known AND (ddd_profile IS DISTINCT FROM jsonb_build_object('identity','umf-ddd-document-validation',
       'version',original_input->'validatorProfile'->>'version','sha256',original_input->'validatorProfile'->>'sha256')
       OR ddd_profile IS DISTINCT FROM doc->'validation'->'dddProfile'
       OR ddd_validation IS DISTINCT FROM doc->'validation'->'dddValidation'
       OR ddd_validation->'valid' IS DISTINCT FROM 'true'::jsonb
       OR jsonb_typeof(ddd_validation->'complete') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(ddd_validation->'diagnostics') IS DISTINCT FROM 'array')
      OR NOT ddd_known AND (validation ? 'dddProfile' OR validation ? 'dddValidation'
       OR doc->'validation' ? 'dddProfile' OR doc->'validation' ? 'dddValidation') THEN
      RAISE EXCEPTION 'original document validation summary required' USING ERRCODE='22023';END IF;
    doc_index:=doc_index+1;
   END LOOP;
  END;
 ELSE
  RAISE EXCEPTION 'Current registration summary required' USING ERRCODE='22023';
 END IF;

 SELECT r.* INTO existing FROM truss.catalog_registration_request r
  WHERE pg_catalog.sha256(r.input_bytes)=pg_catalog.sha256(catalog_accept_with_keys.input_bytes)
  AND r.input_bytes=catalog_accept_with_keys.input_bytes AND CASE WHEN octet_length(r.document_bytes)=0 THEN
   convert_from(truss.runtime_owned_request_documents(r),'UTF8')::jsonb=convert_from(catalog_accept_with_keys.documents_bytes,'UTF8')::jsonb
  ELSE r.document_bytes=catalog_accept_with_keys.documents_bytes AND r.declaration_bytes=catalog_accept_with_keys.declarations_bytes END
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(catalog_accept_with_keys.documents_bytes,'UTF8')::jsonb) d
   WHERE NOT EXISTS(SELECT 1 FROM truss.schema_doc current_doc WHERE current_doc.doc_id=d.value->>'documentId'
    AND current_doc.rev=(SELECT max(latest.rev) FROM truss.schema_doc latest WHERE latest.doc_id=current_doc.doc_id)
    AND current_doc.document=d.value->>'originalText' AND current_doc.doc_revision=d.value->>'revision'));
 IF FOUND THEN
  PERFORM truss.catalog_require_sources(input_bytes,documents_bytes,declarations_bytes);
  IF NOT preview_mode THEN
  INSERT INTO truss.catalog_unchanged_request(installation_id,actor_oid,actor_name,request_key,registration_id,origin_bytes,expected_revision,expected_documents)
   VALUES(installation.installation_id,actor,session_user::text,request_key,existing.registration_id,origin_bytes,expected_revision,expected_documents);
  IF NOT FOUND THEN RAISE EXCEPTION 'unchanged request not stored' USING ERRCODE='55000';END IF;
  END IF;
  alias_request.actor_name:=session_user::text;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN QUERY SELECT existing.revision::text,existing.registration_id::text,r.report_bytes,false,true,alias_request.actor_name,NULL::bytea
   FROM truss.catalog_acceptance_report r WHERE r.rev=existing.revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'original registration report missing' USING ERRCODE='55000'; END IF;
  PERFORM truss.catalog_actor();
  PERFORM truss.catalog_rebind_report_reader(existing.registration_id);
  RETURN;
 END IF;
 PERFORM truss.catalog_require_sources(input_bytes,documents_bytes,declarations_bytes);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(convert_from(documents_bytes,'UTF8')::jsonb) d
  JOIN truss.schema_doc s ON s.doc_id=d.value->>'documentId') THEN
  IF NOT truss.catalog_ddd_optional_evolution_supported(documents_bytes) THEN
   RAISE EXCEPTION 'known DDD source evolution is outside optional-member compatibility' USING ERRCODE='0A000';END IF;
  violations:=truss.catalog_scalar_violations_with_sources(declarations_bytes,documents_bytes);
  IF violations IS NOT NULL THEN
   PERFORM truss.catalog_actor();
   RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;
   RETURN;
  END IF;
 END IF;
 IF prior_revision<> (SELECT coalesce(max(r.revision),0) FROM truss.catalog_registration_request r) THEN
  RAISE EXCEPTION 'complete current catalog head required' USING ERRCODE='55000';END IF;
 IF prior_revision=2147483647 THEN RAISE EXCEPTION 'catalog revision exhausted' USING ERRCODE='54000';END IF;
 new_revision:=prior_revision+1;
 SELECT coalesce(max(type_id),0) INTO type_start FROM truss.type_def;
 SELECT coalesce(max(prop_id),0) INTO property_start FROM truss.prop_def;
 SELECT coalesce(max(rel_type_id),0) INTO relationship_start FROM truss.rel_def;
 IF type_start>2147418111 OR property_start>2147418111 OR relationship_start>2147418111 THEN
  RAISE EXCEPTION 'catalog identity range exhausted' USING ERRCODE='54000';END IF;
 origin:=convert_to((convert_from(origin_bytes,'UTF8')::jsonb||jsonb_build_object('actor',session_user::text,'db_role',session_user::text))::text,'UTF8');
 expected:=truss.catalog_revision_plan(prior_expected,truss.catalog_expected_records(declarations_bytes,documents_bytes,origin,transaction_timestamp(),installation.genesis_at,new_revision,0,0,0));
 -- Input and public-view wire budgets apply to their actual carriers. Source
 -- archives and immutable history are not another request or a rendered view.
 IF jsonb_array_length(expected->'type_def')+jsonb_array_length(expected->'prop_def')+jsonb_array_length(expected->'key_def')+jsonb_array_length(expected->'rel_def')>65536
  THEN RAISE EXCEPTION 'complete catalog resource limit' USING ERRCODE='54000';END IF;
 violations:=truss.catalog_rebind_violations(expected,new_revision);
 IF violations IS NOT NULL THEN
  PERFORM truss.catalog_actor();
  RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;RETURN;
 END IF;
 key_candidates:=truss.catalog_key_backfill_candidates(expected,new_revision);
 IF preview_mode THEN
  RETURN QUERY SELECT prior_revision::text,NULL::text,
   convert_to(jsonb_build_object('interfaceVersion','truss-catalog-key-candidates/0.1','candidates',key_candidates)::text,'UTF8'),
   false,false,session_user::text,NULL::bytea;RETURN;
 END IF;
 verified_keys:=truss.catalog_key_backfill_verify(expected,new_revision,coalesce(key_receipts,convert_to('[]','UTF8')));
 violations:=truss.catalog_key_backfill_violations(verified_keys);
 IF violations IS NOT NULL THEN
  PERFORM truss.catalog_actor();
  RETURN QUERY SELECT prior_revision::text,NULL::text,NULL::bytea,false,false,session_user::text,violations;RETURN;
 END IF;
 FOREACH table_name IN ARRAY ARRAY['schema_rev','schema_doc','type_def','prop_def','key_def','rel_def','relationship_lineage','rel_endpoint','schema_change'] LOOP
  rows:=expected->table_name;
  SELECT string_agg(format('%I',a.attname),',' ORDER BY a.attnum),string_agg(format('%I=EXCLUDED.%I',a.attname,a.attname),',' ORDER BY a.attnum) INTO columns,assignments FROM pg_attribute a
   WHERE a.attrelid=to_regclass('truss.'||table_name) AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='';
  IF table_name='schema_change' THEN
   -- The planner supplies only this new revision's changes.
   INSERT INTO truss.schema_change SELECT p.* FROM truss.catalog_planned_changes(rows) p;
  ELSIF table_name IN ('type_def','prop_def','rel_def') THEN
   identity_column:=CASE table_name WHEN 'type_def' THEN 'type_id' WHEN 'prop_def' THEN 'prop_id' ELSE 'rel_type_id' END;
   EXECUTE format('INSERT INTO truss.%I AS stored(%s) SELECT %s FROM jsonb_populate_recordset(NULL::truss.%I,$1) ON CONFLICT(%I) DO UPDATE SET %s WHERE stored IS DISTINCT FROM EXCLUDED',table_name,columns,columns,table_name,identity_column,assignments) USING rows;
  ELSE
   conflict_columns:=CASE table_name WHEN 'schema_rev' THEN 'rev' WHEN 'schema_doc' THEN 'rev,ord'
    WHEN 'key_def' THEN 'type_id,key_id' WHEN 'relationship_lineage' THEN 'rel_type_id'
    WHEN 'rel_endpoint' THEN 'rel_type_id,source_type,target_type' END;
   EXECUTE format('INSERT INTO truss.%I(%s) SELECT %s FROM jsonb_populate_recordset(NULL::truss.%I,$1) ON CONFLICT(%s) DO NOTHING',table_name,columns,columns,table_name,conflict_columns) USING rows;
  END IF;
 END LOOP;
 request.registration_id:=gen_random_uuid();request.installation_id:=installation.installation_id;
 request.actor_oid:=actor;request.actor_name:=session_user::text;request.request_key:=request_key;
 request.writer_xid:=pg_current_xact_id();request.accepted_at:=transaction_timestamp();request.revision:=new_revision;
 request.expected_revision:=expected_revision;request.expected_documents:=expected_documents;
 request.type_offset:=type_start;request.property_offset:=property_start;request.relationship_offset:=relationship_start;
 request.input_bytes:=input_bytes;request.document_bytes:=CASE WHEN compact THEN ''::bytea ELSE documents_bytes END;
 request.declaration_bytes:=CASE WHEN compact THEN ''::bytea ELSE declarations_bytes END;
 IF compact THEN
  request.source_bytes:=convert_to(jsonb_build_object('sourceFormat','truss-registration-summary/2.0',
   'umf',(convert_from(source_bytes,'UTF8')::jsonb)->'umf',
   'runtimeRelease',jsonb_build_object('id',installation.release_id,'sha256',installation.release_sha256),
   'validationLocation','schema_doc.validation',
   'documentValidations',(SELECT jsonb_agg(jsonb_build_object('documentId',v.value->>'documentId',
    'contentSha256',v.value->>'contentSha256','valid',v.value->'validation'->'valid','complete',v.value->'validation'->'complete') ORDER BY v.ordinality)
    FROM jsonb_array_elements((convert_from(source_bytes,'UTF8')::jsonb)->'documentValidations') WITH ORDINALITY v))::text,'UTF8');
 ELSE request.source_bytes:=source_bytes;END IF;
 request.origin_bytes:=origin_bytes;
 PERFORM truss.catalog_rebind_objects(request,expected);
 PERFORM truss.catalog_key_backfill_apply(request,verified_keys);
 PERFORM truss.catalog_rebind_report_reader(request.registration_id,expected);
 original_report:=truss.catalog_make_report(request,expected);request.report_sha256:=sha256(original_report);
 IF octet_length(original_report)>16777216 THEN RAISE EXCEPTION 'bounded original registration report required' USING ERRCODE='54000';END IF;
 INSERT INTO truss.catalog_acceptance_report VALUES(new_revision,original_report);
 INSERT INTO truss.catalog_registration_request SELECT request.*;
 PERFORM truss.catalog_actor();
 UPDATE truss.schema_head SET rev=new_revision WHERE id=1 AND rev=prior_revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'complete head transition required' USING ERRCODE='55000'; END IF;
 -- Property and key rebinds do not change the graph. Only changed bounded
 -- relationships need a census; a removed max-one bound also needs marker cleanup.
 IF EXISTS(SELECT 1 FROM truss.rel_def r LEFT JOIN truss.schema_change c
   ON c.rev=new_revision AND c.kind='rel' AND c.def_id=r.rel_type_id
   WHERE (r.since_rev=new_revision OR c.def_id IS NOT NULL)
    AND (r.source_min>0 OR r.target_min>0 OR r.source_max IS NOT NULL OR r.target_max IS NOT NULL
     OR (c.before->>'source_max')::int=1 OR (c.before->>'target_max')::int=1)) THEN
  PERFORM truss.runtime_graph_validate(true);
 END IF;
 PERFORM truss.catalog_rebind_report_reader(request.registration_id);
 RETURN QUERY SELECT request.revision::text,request.registration_id::text,original_report,false,false,request.actor_name,NULL::bytea;
END;
$function$
CREATE OR REPLACE FUNCTION truss.get_object(selected_document text, selected_module text, selected_record text, selected_id bigint, maximum_bytes integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE actor_oid oid; selected_type truss.type_def%ROWTYPE; current_object truss.object%ROWTYPE;
 property truss.prop_def%ROWTYPE; cell jsonb; values_json jsonb:='[]'; retained_json jsonb:='[]';
 properties truss.prop_def[];has_row_home boolean;definition_pin text;dependency record;frozen record;
 root_object truss.object;root_definition truss.type_def;root_identity jsonb;
 captured_revision int; result bytea; policy truss.module_access%ROWTYPE; installation truss.catalog_runtime_installation%ROWTYPE;
BEGIN
 actor_oid:=truss.runtime_person(false);
 IF selected_document IS NULL OR selected_module IS NULL OR selected_record IS NULL
 OR octet_length(selected_document) NOT BETWEEN 1 AND 4096 OR octet_length(selected_module) NOT BETWEEN 1 AND 4096
 OR octet_length(selected_record) NOT BETWEEN 1 AND 4096 OR selected_id IS NULL OR selected_id<=0
 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216 THEN
  RAISE EXCEPTION 'bounded object selection required' USING ERRCODE='22023'; END IF;
 IF current_setting('transaction_read_only')='on' THEN
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 ELSE
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1 FOR SHARE NOWAIT;
 END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF expected_release IS DISTINCT FROM installation.release_id OR expected_digest IS DISTINCT FROM installation.release_sha256
 OR installation.release_id<>'truss-catalog-runtime/0.73-candidate' THEN
  RAISE EXCEPTION 'selected installed object runtime required' USING ERRCODE='0A000'; END IF;
 IF captured_revision<1 THEN RAISE EXCEPTION 'accepted read catalog required' USING ERRCODE='0A000'; END IF;
 -- No object observation until exact document/module membership is established.
 IF current_setting('transaction_read_only')='on' THEN
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module;
 ELSE
 SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module FOR SHARE NOWAIT;
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
   SELECT actor_oid UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
   SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid
   WHERE r.rolname::text IN (policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 SELECT * INTO selected_type FROM truss.type_def WHERE document_id=selected_document AND module=selected_module
   AND element=selected_record AND retired_rev IS NULL AND kind='record' AND NOT provisional AND since_rev<=captured_revision;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Require every declaration owner before any object observation.
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
 SELECT coalesce(array_agg(p ORDER BY p.prop_id),ARRAY[]::truss.prop_def[]) INTO properties FROM truss.prop_def p WHERE p.type_id=selected_type.type_id AND p.retired_rev IS NULL;
 SELECT d.definition_pin INTO STRICT definition_pin FROM truss.runtime_owned_definition_metadata('type',selected_type.type_id) d;
 SELECT o AS object,ro AS root_object,rt AS root_definition,
 false AS row_home
 INTO frozen FROM truss.object o
 LEFT JOIN truss.object ro ON ro.id=o.root_id AND ro.type_id=o.root_type
 LEFT JOIN truss.type_def rt ON rt.type_id=ro.type_id AND rt.retired_rev IS NULL AND NOT rt.provisional AND rt.kind='record'
 WHERE o.id=selected_id AND o.type_id=selected_type.type_id;
 IF NOT FOUND THEN RETURN NULL; END IF;
 current_object:=frozen.object;has_row_home:=frozen.row_home;
 root_object:=frozen.root_object;root_definition:=frozen.root_definition;
 IF current_object.root_id IS NOT NULL OR current_object.root_type IS NOT NULL THEN
  IF current_object.root_id IS NULL OR current_object.root_type IS NULL OR root_object.id IS NULL OR root_definition.type_id IS NULL
   OR root_object.root_id IS NOT NULL OR root_object.root_type IS NOT NULL OR root_object.id=current_object.id AND root_object.type_id=current_object.type_id
   THEN
   RAISE EXCEPTION 'current aggregate root required' USING ERRCODE='55000';END IF;
  IF root_object.rev>captured_revision OR root_definition.since_rev>captured_revision THEN
   RAISE EXCEPTION 'catalog changed during ownership observation' USING ERRCODE='55P03';END IF;
  IF NOT truss.runtime_can_read(root_definition.document_id,root_definition.module) THEN RETURN NULL;END IF;
  root_identity:=jsonb_build_object('id',root_object.id::text,'typeId',root_object.type_id::text,
   'definitionPin',(SELECT d.definition_pin FROM truss.runtime_owned_definition_metadata('type',root_object.type_id) d),
   'owner',jsonb_build_object('documentId',root_definition.document_id,'moduleId',root_definition.module));
 END IF;
 result:=truss.render_logical_object(current_object,selected_type,properties,has_row_home,definition_pin,captured_revision,maximum_bytes,installation.release_id,installation.release_sha256,root_identity);
 actor_oid:=truss.runtime_person(false);
 IF current_setting('transaction_read_only')='on' THEN
  SELECT * INTO policy FROM truss.module_access WHERE document_id=selected_document AND module=selected_module;
  IF NOT FOUND THEN RETURN NULL; END IF;
 END IF;
 IF NOT EXISTS(WITH RECURSIVE memberships(role_oid) AS (
   SELECT actor_oid UNION SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid)
   SELECT 1 FROM pg_roles r JOIN memberships m ON m.role_oid=r.oid
   WHERE r.rolname::text IN (policy.reader_role,policy.writer_role)) THEN RETURN NULL; END IF;
 IF NOT truss.runtime_object_values_readable(selected_type.type_id) THEN RETURN NULL;END IF;
 IF root_identity IS NOT NULL AND NOT truss.runtime_can_read(root_definition.document_id,root_definition.module) THEN RETURN NULL;END IF;
 IF (SELECT rev FROM truss.schema_head WHERE id=1) IS DISTINCT FROM captured_revision THEN
  RAISE EXCEPTION 'catalog changed during object observation' USING ERRCODE='55P03';END IF;
 RETURN result;
END;
$function$
CREATE OR REPLACE FUNCTION truss.process_import_chunk(original_input bytea, original_documents bytea, invocation_id uuid, chunk_index integer, expected_release text, expected_digest text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE input jsonb;documents jsonb;context jsonb;group_context jsonb;source_map jsonb;selected record;record jsonb;metadata jsonb;
 payload_bytes bytea;payload jsonb;operation jsonb;group_input jsonb;applied jsonb;created jsonb;state text;code text;
 outcomes jsonb[]:='{}';original_records jsonb[]:='{}';counted int;chunk_size int;total_chunks int;budget_rows int;input_digest text;
 origin jsonb;selected_outcome jsonb;result jsonb;source_at text;
 batch_operations jsonb:='[]';batch_sources jsonb:='[]';batch_records jsonb[]:='{}';batch_outcomes jsonb[]:='{}';batch_done boolean:=false;batch_index int:=0;
BEGIN
 context:=convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb;
 IF original_input IS NULL OR octet_length(original_input)>8388608 OR original_documents IS NULL OR octet_length(original_documents)>4194304 THEN RAISE EXCEPTION 'bounded original import required' USING ERRCODE='54000';END IF;
 IF (convert_from(original_input,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE OR (convert_from(original_documents,'UTF8') IS JSON ARRAY WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'unique original import required' USING ERRCODE='22023';END IF;
 input:=convert_from(original_input,'UTF8')::jsonb;documents:=convert_from(original_documents,'UTF8')::jsonb;
 IF input-ARRAY['interfaceVersion','layoutProfile','importProfile','valueProfile','catalog','loadId','assertedOrigin','records','chunkSize']<>'{}'::jsonb
  OR input->>'interfaceVersion' IS DISTINCT FROM 'truss-batched-import-input/0.1.0'
  OR input->'layoutProfile' IS DISTINCT FROM context->'layoutProfile' OR input->'importProfile' IS DISTINCT FROM context->'importProfile'
  OR input->'valueProfile' IS DISTINCT FROM context->'valueProfile' OR input->'catalog' IS DISTINCT FROM context->'catalog'
  OR jsonb_typeof(input->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(input->'records')>1024
  OR jsonb_typeof(input->'chunkSize') IS DISTINCT FROM 'string' OR input->>'chunkSize' !~ '^[1-9][0-9]{0,2}$'
  OR (input->>'chunkSize')::int>128 OR jsonb_typeof(input->'loadId') IS DISTINCT FROM 'string' OR octet_length(input->>'loadId') NOT BETWEEN 1 AND 4096
  OR jsonb_typeof(input->'assertedOrigin') IS DISTINCT FROM 'object' OR input->'assertedOrigin'->>'kind' IS DISTINCT FROM 'map'
  OR jsonb_typeof(input->'assertedOrigin'->'entries') IS DISTINCT FROM 'array'
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e WHERE e.value->>'key'='x-load-id' OR e.value->'value'->>'kind' NOT IN ('null','string'))
  OR (SELECT count(*)<>count(DISTINCT e.value->>'key') FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e)
  THEN RAISE EXCEPTION 'selected original chunk profile required' USING ERRCODE='22023';END IF;
 IF (input->'assertedOrigin')-ARRAY['kind','entries']<>'{}'::jsonb
  OR jsonb_array_length(input->'assertedOrigin'->'entries')>1024
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(input->'assertedOrigin'->'entries') e WHERE
   jsonb_typeof(e.value) IS DISTINCT FROM 'object' OR e.value-ARRAY['key','value']<>'{}'::jsonb
   OR jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string' OR jsonb_typeof(e.value->'value') IS DISTINCT FROM 'object'
   OR (e.value->'value')-ARRAY['kind','text']<>'{}'::jsonb
   OR (e.value->'value'->>'kind' IN ('null','string')) IS NOT TRUE
   OR e.value->'value'->>'kind'='null' AND e.value->'value' ? 'text'
   OR e.value->'value'->>'kind'='string' AND jsonb_typeof(e.value->'value'->'text') IS DISTINCT FROM 'string') THEN
  RAISE EXCEPTION 'closed original asserted origin required' USING ERRCODE='22023';END IF;
 origin:=jsonb_set(input->'assertedOrigin','{entries}',(input->'assertedOrigin'->'entries')||jsonb_build_array(jsonb_build_object('key','x-load-id','value',jsonb_build_object('kind','string','text',input->>'loadId'))));
 IF octet_length((input->'assertedOrigin')::text)>1048576 OR octet_length(origin::text)>1048576 THEN
  RAISE EXCEPTION 'bounded original asserted origin required' USING ERRCODE='54000';END IF;
 chunk_size:=(input->>'chunkSize')::int;counted:=jsonb_array_length(input->'records');total_chunks:=greatest(1,(counted+chunk_size-1)/chunk_size);
 IF invocation_id IS NULL OR chunk_index IS NULL OR chunk_index<0 OR chunk_index>=total_chunks THEN RAISE EXCEPTION 'derived original chunk required' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(documents)>512 OR EXISTS(SELECT 1 FROM jsonb_array_elements(documents) d WHERE d.value-ARRAY['documentId','sourceText']<>'{}'::jsonb OR jsonb_typeof(d.value->'sourceText') IS DISTINCT FROM 'string')
  OR (SELECT count(*)<>count(DISTINCT d.value->>'documentId') FROM jsonb_array_elements(documents) d) THEN RAISE EXCEPTION 'complete unique original documents required' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_object_agg(d.value->>'documentId',d.value->>'sourceText'),'{}') INTO source_map FROM jsonb_array_elements(documents) d;
 -- Byte/hash admission precedes identity routing, including skipped records.
 -- Payload interpretation remains after the native live/reserved-identity skip.
 FOR record IN SELECT value FROM jsonb_array_elements(input->'records') LOOP
  IF jsonb_typeof(record) IS DISTINCT FROM 'object' OR record-ARRAY['kind','identity','payload','payloadProfile']<>'{}'::jsonb
   OR (record->>'kind' IN ('object','edge')) IS NOT TRUE OR record->'payloadProfile' IS DISTINCT FROM context->'importPayloadProfile'
   OR jsonb_typeof(record->'payload') IS DISTINCT FROM 'object' OR (record->'payload')-ARRAY['identity','bytesBase64','sha256']<>'{}'::jsonb THEN RAISE EXCEPTION 'closed original import record required' USING ERRCODE='22023';END IF;
  payload_bytes:=decode(record->'payload'->>'bytesBase64','base64');
  IF record->'payload'->>'identity' IS DISTINCT FROM record->'payload'->>'sha256' OR payload_bytes IS NULL OR octet_length(payload_bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(payload_bytes),'hex') IS DISTINCT FROM record->'payload'->>'sha256' THEN RAISE EXCEPTION 'original payload byte integrity required' USING ERRCODE='22023';END IF;
 END LOOP;
 -- Only finished transactions below every active snapshot are eligible; cleanup
 -- is bounded independently of this call's admitted work.
 DELETE FROM truss.runtime_import_budget WHERE writer_xid IN
  (SELECT writer_xid FROM truss.runtime_import_budget WHERE writer_xid<pg_snapshot_xmin(pg_current_snapshot()) ORDER BY writer_xid LIMIT 128);
 INSERT INTO truss.runtime_import_budget VALUES(pg_current_xact_id(),least(chunk_size,greatest(0,counted-chunk_index*chunk_size)),octet_length(original_input)+octet_length(original_documents))
 ON CONFLICT(writer_xid) DO UPDATE SET records=truss.runtime_import_budget.records+EXCLUDED.records,submitted_bytes=truss.runtime_import_budget.submitted_bytes+EXCLUDED.submitted_bytes
 WHERE truss.runtime_import_budget.records+EXCLUDED.records<=4096 AND truss.runtime_import_budget.submitted_bytes+EXCLUDED.submitted_bytes<=268435456;
 GET DIAGNOSTICS budget_rows=ROW_COUNT;IF budget_rows<>1 THEN RAISE EXCEPTION 'cumulative import work budget exceeded' USING ERRCODE='54000';END IF;
 group_context:=convert_from(truss.group_context(expected_release,expected_digest),'UTF8')::jsonb;
 -- Independent new rootless objects can share the existing set-based group
 -- writer. A contained eligibility/constraint failure falls through to the
 -- original per-record semantics; stale admission, resource, cancellation and
 -- transaction-retry failures are never retried here.
 IF least(chunk_size,greatest(0,counted-chunk_index*chunk_size))>1 THEN
  BEGIN
   FOR selected IN SELECT value AS record,(ordinality-1)::int AS input_index FROM jsonb_array_elements(input->'records') WITH ORDINALITY
    ORDER BY (value->>'kind'='edge'),ordinality OFFSET chunk_index*chunk_size LIMIT chunk_size LOOP
    record:=selected.record;
    IF record->>'kind' IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'independent object run required' USING ERRCODE='TRB01';END IF;
    metadata:=convert_from(truss.import_object_identity(convert_to((record->'identity')::text,'UTF8'),convert_to(source_map->>(record->'identity'->'type'->'owner'->>'documentId'),'UTF8'),NULL,expected_release,expected_digest),'UTF8')::jsonb;
    IF metadata->>'state'='skipped' THEN RAISE EXCEPTION 'per-record skip precedence required' USING ERRCODE='TRB01';END IF;
    operation:=truss.runtime_import_operation(record,metadata);
    batch_operations:=batch_operations||jsonb_build_array(operation);
    batch_records:=array_append(batch_records,jsonb_build_object('inputIndex',selected.input_index::text,'record',record));
    batch_sources:=batch_sources||jsonb_build_array(jsonb_build_object('operationIndex',batch_index,
     'originalRecordBase64',replace(encode(convert_to(record::text,'UTF8'),'base64'),E'\n','')));
    batch_index:=batch_index+1;
   END LOOP;
   group_input:=jsonb_build_object('interfaceVersion','truss-group-input/0.1.0','layoutProfile',group_context->'layoutProfile','mutationProfile',group_context->'mutationProfile','valueProfile',group_context->'valueProfile','catalog',jsonb_build_object('selection','current'),'preconditions','[]'::jsonb,'operations',batch_operations,'assertedOrigin',origin);
   IF octet_length(group_input::text)>4194304 THEN RAISE EXCEPTION 'per-record envelope required' USING ERRCODE='TRB01';END IF;
   applied:=convert_from(truss.apply_group(convert_to(group_input::text,'UTF8'),original_documents,convert_to('{"state":"none"}','UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
   IF applied->>'outcome'<>'success' THEN
    state:=CASE WHEN applied->>'outcome'='failed' THEN coalesce(applied->>'nativeState','22023') WHEN applied->>'reason'='resource' THEN '54000' WHEN applied->>'reason'='observation' THEN '55P03' ELSE '0A000' END;
    RAISE EXCEPTION 'independent import group refused' USING ERRCODE=state;
   END IF;
   PERFORM truss.runtime_owned_import_record_sources((applied->>'attemptId')::uuid,batch_sources,input->>'loadId');
   FOR batch_index IN 0..array_length(batch_records,1)-1 LOOP
    created:=applied->'semantic'->'results'->batch_index;
    batch_outcomes:=array_append(batch_outcomes,jsonb_build_object('inputIndex',batch_records[batch_index+1]->>'inputIndex',
     'outcome','created','identity',created->'identity','version',created->>'version','groupAttemptId',applied->>'attemptId'));
   END LOOP;
   original_records:=batch_records;outcomes:=batch_outcomes;batch_done:=true;
  EXCEPTION WHEN SQLSTATE 'TRB01' OR SQLSTATE '22023' OR SQLSTATE '23505' OR SQLSTATE '42501' OR SQLSTATE '0A000' OR SQLSTATE 'P1004' OR SQLSTATE 'P1005' THEN
   -- This entire block's database effects have rolled back. Nothing from the
   -- rejected group may enter the original-record/outcome/provenance report.
   batch_done:=false;
  END;
 END IF;
 IF NOT batch_done THEN
 FOR selected IN SELECT value AS record,(ordinality-1)::int AS input_index FROM jsonb_array_elements(input->'records') WITH ORDINALITY
  ORDER BY (value->>'kind'='edge'),ordinality OFFSET chunk_index*chunk_size LIMIT chunk_size LOOP
  record:=selected.record;original_records:=array_append(original_records,jsonb_build_object('inputIndex',selected.input_index::text,'record',record));
  code:=NULL;
  BEGIN
   IF record->'payloadProfile' IS DISTINCT FROM context->'importPayloadProfile' THEN RAISE EXCEPTION 'selected payload profile required' USING ERRCODE='0A000';END IF;
   IF record->>'kind'='object' THEN
    metadata:=convert_from(truss.import_object_identity(convert_to((record->'identity')::text,'UTF8'),convert_to(source_map->>(record->'identity'->'type'->'owner'->>'documentId'),'UTF8'),NULL,expected_release,expected_digest),'UTF8')::jsonb;
   ELSIF record->>'kind'='edge' THEN metadata:=convert_from(truss.import_edge_identity(convert_to((record->'identity')::text,'UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
   ELSE RAISE EXCEPTION 'object or edge import required' USING ERRCODE='22023';END IF;
   IF metadata->>'state'='skipped' THEN
    selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','skipped','reason',metadata->>'reason');
    IF metadata ? 'identity' THEN selected_outcome:=selected_outcome||jsonb_build_object('identity',metadata->'identity');END IF;
   ELSE
    code:='invalid_payload';
    operation:=truss.runtime_import_operation(record,metadata);
    group_input:=jsonb_build_object('interfaceVersion','truss-group-input/0.1.0','layoutProfile',group_context->'layoutProfile','mutationProfile',group_context->'mutationProfile','valueProfile',group_context->'valueProfile','catalog',jsonb_build_object('selection','current'),'preconditions','[]'::jsonb,'operations',jsonb_build_array(operation),'assertedOrigin',origin);
    code:=NULL;
    applied:=convert_from(truss.apply_group(convert_to(group_input::text,'UTF8'),original_documents,convert_to('{"state":"none"}','UTF8'),expected_release,expected_digest),'UTF8')::jsonb;
    IF applied->>'outcome'<>'success' THEN
     state:=CASE WHEN applied->>'outcome'='failed' THEN applied->>'nativeState' WHEN applied->>'reason'='resource' THEN '54000' WHEN applied->>'reason'='observation' THEN '55P03' ELSE '0A000' END;
     IF state IS NULL THEN state:='22023';END IF;RAISE EXCEPTION 'import record refused' USING ERRCODE=state;
    END IF;
    created:=applied->'semantic'->'results'->0;
    PERFORM truss.import_record_source((applied->>'attemptId')::uuid,convert_to(record::text,'UTF8'),input->>'loadId');
    selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','created','identity',created->'identity','version',created->>'version','groupAttemptId',applied->>'attemptId');
   END IF;
  EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '23505' OR SQLSTATE '42501' OR SQLSTATE '0A000' OR SQLSTATE 'P1004' OR SQLSTATE 'P1005' THEN
   GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE;
   code:=coalesce(code,CASE state WHEN '22023' THEN 'invalid' WHEN '23505' THEN 'conflict' WHEN '42501' THEN 'unauthorized' WHEN '0A000' THEN 'unsupported_profile' WHEN 'P1004' THEN 'missing_endpoint' ELSE 'dependencies' END);
   selected_outcome:=jsonb_build_object('inputIndex',selected.input_index::text,'outcome','rejected','code',code);
  END;
  outcomes:=array_append(outcomes,selected_outcome);
 END LOOP;
 END IF;
 FOR selected IN SELECT r.value AS original,o.value AS result FROM unnest(original_records) r(value) JOIN unnest(outcomes) o(value) ON r.value->>'inputIndex'=o.value->>'inputIndex' LOOP
  IF selected.result->>'outcome' IN ('created','skipped') THEN PERFORM truss.import_report_record_authority(convert_to(jsonb_build_object('originalIdentity',selected.original->'record'->'identity','outcomeIdentity',selected.result->'identity')::text,'UTF8'),selected.original->'record'->>'kind',expected_release,expected_digest);END IF;
 END LOOP;
 IF convert_from(truss.batched_import_context(expected_release,expected_digest),'UTF8')::jsonb IS DISTINCT FROM context THEN RAISE EXCEPTION 'original import context changed' USING ERRCODE='42501';END IF;
 input_digest:=encode(sha256(convert_to('truss-batched-import-input/0.1.0'||chr(10),'UTF8')||original_input),'hex');
 PERFORM truss.runtime_record_import_load(invocation_id,chunk_index,total_chunks,input->>'loadId',input->'assertedOrigin',input_digest,counted,input->'records',to_jsonb(original_records),to_jsonb(outcomes),expected_release,expected_digest);
 result:=jsonb_build_object('context',context,'outcomes',to_jsonb(outcomes),'hostTransactionId','truss-pending-transaction:'||(context->>'sourceEpoch')||':'||pg_current_xact_id()::text);
 IF octet_length(result::text)>8388608 THEN RAISE EXCEPTION 'bounded complete import report required' USING ERRCODE='54000';END IF;
 RETURN convert_to(result::text,'UTF8');
END;
$function$
CREATE OR REPLACE FUNCTION truss.query_binding_if_changed(selected_documents jsonb, maximum_scan_rows integer, maximum_result_rows integer, maximum_bytes integer, expected_release text, expected_digest text, validator text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;captured_revision int;actor oid;selected_document_id text;
 compiled record;dependency jsonb;pins jsonb:='[]';readers jsonb:='[]';current_validator text;bundle bytea;result bytea;
BEGIN
 actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF installation.release_id IS DISTINCT FROM expected_release OR installation.release_sha256 IS DISTINCT FROM expected_digest THEN
  RAISE EXCEPTION 'selected query release required' USING ERRCODE='0A000';END IF;
 IF maximum_scan_rows IS NULL OR maximum_scan_rows NOT BETWEEN 1 AND 10000 OR maximum_result_rows IS NULL OR maximum_result_rows NOT BETWEEN 1 AND 10000 OR maximum_bytes IS NULL OR maximum_bytes NOT BETWEEN 1 AND 16777216
 OR jsonb_typeof(selected_documents) IS DISTINCT FROM 'array' OR jsonb_array_length(selected_documents) NOT BETWEEN 1 AND 32
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(selected_documents) v WHERE jsonb_typeof(v.value)<>'string')
 OR (SELECT count(DISTINCT v.value) FROM jsonb_array_elements(selected_documents) v)<>jsonb_array_length(selected_documents)
 OR validator IS NOT NULL AND validator !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'bounded original query validator request required' USING ERRCODE='22023';END IF;
 SELECT rev INTO STRICT captured_revision FROM truss.schema_head WHERE id=1;
 FOR selected_document_id IN SELECT value FROM jsonb_array_elements_text(selected_documents) LOOP
  SELECT metadata->'pin' AS pin,metadata->'readers' AS readers INTO compiled
   FROM truss.runtime_document_schema WHERE rev=captured_revision AND doc_id=selected_document_id;
  IF NOT FOUND OR compiled.pin IS NULL OR jsonb_typeof(compiled.readers) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'current original query schema required' USING ERRCODE='0A000';END IF;
  pins:=pins||jsonb_build_array(compiled.pin);readers:=readers||compiled.readers;
 END LOOP;
 FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
  IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',actor) THEN
   RAISE EXCEPTION 'complete current query reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 current_validator:=encode(sha256(convert_to(jsonb_build_object(
  'installation',installation.installation_id::text,'release',expected_release,'digest',expected_digest,
  'revision',captured_revision,'documents',pins,'person',actor::text,'sessionUser',session_user,
  'maximumScanRows',maximum_scan_rows,'maximumResultRows',maximum_result_rows,'maximumBytes',maximum_bytes)::text,'UTF8')),'hex');
 IF validator IS NOT NULL AND validator=current_validator THEN
  result:=convert_to(jsonb_build_object('outcome','unchanged','validator',current_validator)::text,'UTF8');
 ELSE
  bundle:=truss.query_binding(selected_documents,maximum_scan_rows,maximum_result_rows,maximum_bytes,expected_release,expected_digest);
  result:=convert_to(jsonb_build_object('outcome','snapshot','validator',current_validator,
   'bundle',convert_from(bundle,'UTF8')::jsonb)::text,'UTF8');
 END IF;
 -- Do not publish a warm hint after a role/dependency change during observation.
 IF truss.runtime_person(false) IS DISTINCT FROM actor OR captured_revision IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1) THEN
  RAISE EXCEPTION 'query basis changed during observation' USING ERRCODE='55P03';END IF;
 FOR dependency IN SELECT value FROM jsonb_array_elements(readers) LOOP
  IF NOT truss.runtime_can_read_qualified(dependency->>'documentId',dependency->>'moduleId',actor) THEN
   RAISE EXCEPTION 'complete current query reader required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF octet_length(result)>maximum_bytes THEN RAISE EXCEPTION 'conditional query binding byte limit' USING ERRCODE='54000';END IF;
 RETURN result;
END;
$function$
CREATE OR REPLACE FUNCTION truss.query_scope(binding jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
AS $function$
DECLARE installation truss.catalog_runtime_installation%ROWTYPE;selected_document jsonb;selected_record jsonb;selected_field jsonb;source truss.schema_doc%ROWTYPE;owner truss.type_def%ROWTYPE;property truss.prop_def%ROWTYPE;module jsonb;selected_relation jsonb;relation truss.rel_def%ROWTYPE;selected_key jsonb;key_definition truss.key_def%ROWTYPE;current_actor oid;compiled jsonb;
BEGIN
 current_actor:=truss.runtime_person(false);
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF jsonb_typeof(binding) IS DISTINCT FROM 'object' OR binding->>'interfaceVersion' IS DISTINCT FROM 'truss-runtime-binding/0.5'
 OR binding->'queryAbi' IS DISTINCT FROM truss.query_abi()
 OR binding-ARRAY['interfaceVersion','queryAbi','schema','installationId','releaseId','releaseSha256','catalogRevision','documents','records','relationships','maximumScanRows','maximumResultRows','maximumBytes']<>'{}'::jsonb
 OR binding->>'schema' IS DISTINCT FROM 'truss' OR binding->>'installationId' IS DISTINCT FROM installation.installation_id::text
 OR binding->>'releaseId' IS DISTINCT FROM installation.release_id OR binding->>'releaseSha256' IS DISTINCT FROM installation.release_sha256
 OR installation.release_id<>'truss-catalog-runtime/0.73-candidate' OR (binding->>'catalogRevision')::int IS DISTINCT FROM (SELECT rev FROM truss.schema_head WHERE id=1)
 OR binding->>'maximumResultRows' IS NULL OR (binding->>'maximumResultRows')::int NOT BETWEEN 1 AND 10000 OR binding->>'maximumScanRows' IS NULL OR binding->>'maximumBytes' IS NULL OR (binding->>'maximumScanRows')::int NOT BETWEEN 1 AND 10000 OR (binding->>'maximumBytes')::int NOT BETWEEN 1 AND 16777216
 OR octet_length(binding::text)>4194304 OR jsonb_typeof(binding->'documents') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'documents') NOT BETWEEN 1 AND 32
 OR jsonb_typeof(binding->'relationships') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'relationships')>1024
 OR jsonb_typeof(binding->'records') IS DISTINCT FROM 'array' OR jsonb_array_length(binding->'records') NOT BETWEEN 1 AND 1024 THEN
  RAISE EXCEPTION 'selected query context required' USING ERRCODE='0A000';END IF;
 IF jsonb_array_length(binding->'documents')=1 THEN
  SELECT metadata INTO compiled FROM truss.runtime_document_schema
   WHERE rev=(binding->>'catalogRevision')::int AND doc_id=binding->'documents'->0->>'documentId';
  IF compiled->'pin'=binding->'documents'->0 AND compiled->'records'=binding->'records'
   AND compiled->'relationships'=binding->'relationships' AND compiled->'closed'='true'::jsonb AND compiled->'itemsValid'='true'::jsonb THEN
   FOR selected_document IN SELECT value FROM jsonb_array_elements(compiled->'readers') LOOP
    IF NOT truss.runtime_can_read_qualified(selected_document->>'documentId',selected_document->>'moduleId',current_actor) THEN
     RAISE EXCEPTION 'complete selected_document reader required' USING ERRCODE='42501';END IF;
   END LOOP;
   RETURN;
  END IF;
 END IF;
 FOR selected_document IN SELECT value FROM jsonb_array_elements(binding->'documents') LOOP
  SELECT * INTO source FROM truss.schema_doc d WHERE d.doc_id=selected_document->>'documentId' AND d.rev<= (binding->>'catalogRevision')::int ORDER BY d.rev DESC LIMIT 1;
  IF NOT FOUND OR source.doc_revision IS DISTINCT FROM selected_document->>'revision' OR source.content_sha256 IS DISTINCT FROM selected_document->>'sha256' THEN RAISE EXCEPTION 'original query source changed' USING ERRCODE='55P03';END IF;
  -- Full original source bytes are supplied only under complete selected_document scope.
  FOR module IN SELECT value FROM jsonb_array_elements(source.document::jsonb->'modules') LOOP
   IF NOT truss.runtime_can_read(source.doc_id,module->>'id') THEN RAISE EXCEPTION 'complete selected_document reader required' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 FOR selected_record IN SELECT value FROM jsonb_array_elements(binding->'records') LOOP
  SELECT * INTO owner FROM truss.type_def t WHERE t.type_id=(selected_record->>'typeId')::int AND t.retired_rev IS NULL AND NOT t.provisional AND t.kind='record';
  IF NOT FOUND OR owner.document_id IS DISTINCT FROM selected_record->'identity'->>'documentId' OR owner.module IS DISTINCT FROM selected_record->'identity'->>'module' OR owner.element IS DISTINCT FROM selected_record->'identity'->>'element'
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d WHERE d.value->>'documentId'=owner.document_id AND d.value->>'revision'=selected_record->'identity'->>'revision')
   OR NOT truss.runtime_can_read(owner.document_id,owner.module) THEN RAISE EXCEPTION 'accepted authorized query record required' USING ERRCODE='42501';END IF;
  IF jsonb_typeof(selected_record->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(selected_record->'fields')<>(SELECT count(*) FROM truss.prop_def p WHERE p.type_id=owner.type_id AND p.retired_rev IS NULL)
   OR (SELECT count(DISTINCT f.value->>'propertyId') FROM jsonb_array_elements(selected_record->'fields') f)<>jsonb_array_length(selected_record->'fields') THEN RAISE EXCEPTION 'complete property mapping required' USING ERRCODE='0A000';END IF;
  IF truss.runtime_object_values_readable(owner.type_id) IS NOT TRUE THEN RAISE EXCEPTION 'current query interpretation reader required' USING ERRCODE='42501';END IF;
  FOR selected_field IN SELECT value FROM jsonb_array_elements(selected_record->'fields') LOOP
   SELECT * INTO property FROM truss.prop_def p WHERE p.type_id=owner.type_id AND p.prop_id=(selected_field->>'propertyId')::int AND p.retired_rev IS NULL;
   IF NOT FOUND OR property.element IS DISTINCT FROM selected_field->'identity'->>'element' OR property.declaration_module IS DISTINCT FROM selected_field->'identity'->>'module'
    OR selected_field->'identity'->>'documentId' IS DISTINCT FROM owner.document_id OR selected_field->'identity'->>'revision' IS DISTINCT FROM selected_record->'identity'->>'revision'
    OR NOT truss.runtime_can_read(owner.document_id,property.declaration_module) THEN RAISE EXCEPTION 'accepted authorized property mapping required' USING ERRCODE='42501';END IF;
  END LOOP;
  IF jsonb_typeof(selected_record->'keys') IS DISTINCT FROM 'array' OR jsonb_array_length(selected_record->'keys')<>(SELECT count(*) FROM truss.key_def k WHERE k.type_id=owner.type_id AND k.retired_rev IS NULL)
   OR (SELECT count(DISTINCT k.value->>'keyId') FROM jsonb_array_elements(selected_record->'keys') k)<>jsonb_array_length(selected_record->'keys') THEN RAISE EXCEPTION 'complete current key mapping required' USING ERRCODE='0A000';END IF;
  FOR selected_key IN SELECT value FROM jsonb_array_elements(selected_record->'keys') LOOP
   SELECT * INTO key_definition FROM truss.key_def k WHERE k.type_id=owner.type_id AND k.key_id=selected_key->>'keyId' AND k.retired_rev IS NULL;
   IF NOT FOUND OR selected_key->'propertyIds' IS DISTINCT FROM (SELECT coalesce(jsonb_agg(p.prop_id::text ORDER BY p.n),'[]') FROM unnest(key_definition.prop_ids) WITH ORDINALITY p(prop_id,n)) THEN
    RAISE EXCEPTION 'exact ordered native key mapping required' USING ERRCODE='55000';END IF;
  END LOOP;
 END LOOP;
 FOR selected_relation IN SELECT value FROM jsonb_array_elements(binding->'relationships') LOOP
  SELECT * INTO relation FROM truss.rel_def r WHERE r.rel_type_id=(selected_relation->>'relationshipTypeId')::int AND r.retired_rev IS NULL;
  IF NOT FOUND OR relation.document_id IS DISTINCT FROM selected_relation->'identity'->>'documentId' OR relation.module IS DISTINCT FROM selected_relation->'identity'->>'module'
   OR relation.rel_id IS DISTINCT FROM selected_relation->'identity'->>'relationship' OR relation.lifecycle NOT IN ('independent','owned') OR NOT relation.directed OR relation.composition OR relation.assoc_type_id IS NOT NULL
   OR NOT truss.runtime_can_read(relation.document_id,relation.module)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'documents') d WHERE d.value->>'documentId'=relation.document_id AND d.value->>'revision'=selected_relation->'identity'->>'revision')
   OR (SELECT count(*) FROM truss.rel_endpoint e WHERE e.rel_type_id=relation.rel_type_id)<>1
   OR NOT EXISTS(SELECT 1 FROM truss.rel_endpoint e WHERE e.rel_type_id=relation.rel_type_id AND e.source_type=(selected_relation->>'sourceTypeId')::int AND e.target_type=(selected_relation->>'targetTypeId')::int)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE r.value->>'typeId'=selected_relation->>'sourceTypeId')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(binding->'records') r WHERE r.value->>'typeId'=selected_relation->>'targetTypeId') THEN
   RAISE EXCEPTION 'accepted authorized relationship mapping required' USING ERRCODE='42501';END IF;
 END LOOP;
END;
$function$
CREATE OR REPLACE FUNCTION truss.runtime_import_operation(record jsonb, metadata jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE payload_bytes bytea;payload jsonb;operation jsonb;source_at text;
BEGIN
    payload_bytes:=decode(record->'payload'->>'bytesBase64','base64');
    IF octet_length(payload_bytes) NOT BETWEEN 1 AND 1048576 OR encode(sha256(payload_bytes),'hex') IS DISTINCT FROM record->'payload'->>'sha256'
     OR (convert_from(payload_bytes,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'original payload integrity required' USING ERRCODE='22023';END IF;
    payload:=convert_from(payload_bytes,'UTF8')::jsonb;
    IF payload->>'interfaceVersion' IS DISTINCT FROM 'truss-import-payload/0.1.0' OR payload->>'kind' IS DISTINCT FROM record->>'kind' THEN RAISE EXCEPTION 'exact original payload required' USING ERRCODE='22023';END IF;
    IF jsonb_typeof(payload->'values') IS DISTINCT FROM 'array'
     OR jsonb_array_length(payload->'values')>1024
     OR (SELECT count(*)<>count(DISTINCT v.value->>'name') FROM jsonb_array_elements(payload->'values') v)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'values') v WHERE jsonb_typeof(v.value) IS DISTINCT FROM 'object'
      OR v.value-ARRAY['name','value']<>'{}'::jsonb OR jsonb_typeof(v.value->'name') IS DISTINCT FROM 'string') THEN
     RAISE EXCEPTION 'unique original authored values required' USING ERRCODE='22023';END IF;
    IF record->>'kind'='object' THEN
     IF payload-ARRAY['interfaceVersion','kind','values','ownership','source']<>'{}'::jsonb
      OR payload->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(metadata->'primaryFields') f WHERE NOT EXISTS(
       SELECT 1 FROM jsonb_array_elements(payload->'values') v WHERE v.value->>'name'=f.value->>'name' AND v.value->'value'=f.value->'value')) THEN
      RAISE EXCEPTION 'original primary field/payload agreement required' USING ERRCODE='22023';END IF;
    ELSIF payload-ARRAY['interfaceVersion','kind','values','orderKey','source']<>'{}'::jsonb
     OR payload->'orderKey' IS DISTINCT FROM '{"state":"null"}'::jsonb AND
      (jsonb_typeof(payload->'orderKey') IS DISTINCT FROM 'object' OR (payload->'orderKey')-ARRAY['state','text']<>'{}'::jsonb
       OR payload->'orderKey'->>'state' IS DISTINCT FROM 'text' OR jsonb_typeof(payload->'orderKey'->'text') IS DISTINCT FROM 'string') THEN
     RAISE EXCEPTION 'closed original edge payload required' USING ERRCODE='22023';END IF;
    IF payload ? 'source' AND (jsonb_typeof(payload->'source') IS DISTINCT FROM 'object'
     OR (payload->'source')-ARRAY['kind','entries']<>'{}'::jsonb OR payload->'source'->>'kind' IS DISTINCT FROM 'map'
     OR jsonb_typeof(payload->'source'->'entries') IS DISTINCT FROM 'array'
     OR (SELECT count(*)<>count(DISTINCT e.value->>'key') FROM jsonb_array_elements(payload->'source'->'entries') e)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'source'->'entries') e WHERE e.value-ARRAY['key','value']<>'{}'::jsonb
      OR jsonb_typeof(e.value->'key') IS DISTINCT FROM 'string' OR e.value->>'key' IN ('author','at','system') AND
       (e.value->'value'->>'kind' IN ('string','null')) IS NOT TRUE)) THEN
     RAISE EXCEPTION 'closed original source fields required' USING ERRCODE='22023';END IF;
    SELECT e.value->'value'->>'text' INTO source_at FROM jsonb_array_elements(coalesce(payload->'source'->'entries','[]'::jsonb)) e WHERE e.value->>'key'='at' AND e.value->'value'->>'kind'='string';
    IF source_at IS NOT NULL THEN
     BEGIN PERFORM truss.query_timestamp_instant_key(source_at,'umf-rfc3339-exact-instant/1.0.0');
     EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'selected source.at exact instant required' USING ERRCODE='22023';END;
    END IF;
    IF record->>'kind'='object' THEN operation:=jsonb_build_object('operation','create_object','typeDefinitionPin',metadata->>'definitionPin','values',payload->'values','ownership',payload->'ownership');
    ELSE operation:=jsonb_build_object('operation','create_edge','relationshipDefinitionPin',record->'identity'->>'relationshipDefinitionPin','source',jsonb_build_object('state','stored','identity',record->'identity'->'source'),'target',jsonb_build_object('state','stored','identity',record->'identity'->'target'),'values',payload->'values','orderKey',payload->'orderKey');END IF;
    RETURN operation;
    EXCEPTION WHEN SQLSTATE '22021' OR SQLSTATE '22P05' OR SQLSTATE '22P02' THEN
     RAISE EXCEPTION 'eligible original payload encoding required' USING ERRCODE='22023';
END;
$function$
CREATE OR REPLACE FUNCTION truss.runtime_owned_import_record_source_checked(checked_attempt uuid, checked_next_index integer, checked_writer_xid xid8, checked_operation jsonb, checked_result jsonb, owned_profile_matches boolean, load_id_asserted boolean, selected_index integer, original_record bytea, load_id text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
 SET row_security TO 'off'
 SET "TimeZone" TO 'UTC'
 SET bytea_output TO 'hex'
AS $function$
DECLARE selected_attempt uuid:=checked_attempt;record jsonb;payload bytea;value jsonb;operation jsonb:=checked_operation;result jsonb:=checked_result;source_value jsonb:='{}';source_invalid boolean;component_invalid boolean;expected_source jsonb;source_row truss.record_source%ROWTYPE;kind char(1);metadata jsonb;selected_type truss.type_def%ROWTYPE;owned_selection boolean;root_identity jsonb;resolved_source_identity jsonb;resolved_target_identity jsonb;source_entity_id bigint;inserted_rows int;
BEGIN
 IF selected_index IS NULL OR selected_index<0 OR selected_index>=checked_next_index THEN RAISE EXCEPTION 'current complete indexed import group required' USING ERRCODE='55000';END IF;
 IF original_record IS NULL OR octet_length(original_record) NOT BETWEEN 1 AND 2097152 OR (convert_from(original_record,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE
  OR load_id IS NULL OR octet_length(load_id) NOT BETWEEN 1 AND 4096 THEN RAISE EXCEPTION 'bounded original import record/load required' USING ERRCODE='22023';END IF;
 record:=convert_from(original_record,'UTF8')::jsonb;payload:=decode(record->'payload'->>'bytesBase64','base64');
 IF record-ARRAY['kind','identity','payload','payloadProfile']<>'{}'::jsonb OR (record->>'kind' IN ('object','edge')) IS NOT TRUE THEN RAISE EXCEPTION 'closed import record required' USING ERRCODE='22023';END IF;
 IF octet_length(payload) NOT BETWEEN 1 AND 1048576 OR (convert_from(payload,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'bounded unique original payload required' USING ERRCODE='22023';END IF;
 value:=convert_from(payload,'UTF8')::jsonb;
 owned_selection:=record->'payloadProfile'=truss.runtime_import_profiles()->'ownedImportPayloadProfile';
 -- Indexed rootless object batches use the same original scalar payload. Only
 -- the indexed batch facade reaches this form; the legacy one-record facade
 -- retains its one-operation check. All payload/key/actual-root checks below
 -- still apply to the exact selected native operation and result.
 IF owned_selection IS NOT TRUE AND (selected_index<>0 OR checked_next_index<>1)
  AND (owned_profile_matches IS TRUE AND record->>'kind'='object'
   AND operation->>'operation'='create_object' AND operation->'ownership'='{"state":"rootless"}'::jsonb) IS NOT TRUE THEN
  RAISE EXCEPTION 'legacy one-create import group required' USING ERRCODE='0A000';END IF;

 IF (record->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'ownedImportPayloadProfile'
  AND record->'payloadProfile' IS DISTINCT FROM truss.runtime_import_profiles()->'importPayloadProfile'
  AND NOT ((record->'payloadProfile'='{"identity":"truss-scalar-import-payload","version":"0.2","sha256":"45180a79836394b3c3c945cfe908b67e3a45ab3c81362f052b12ae45e7042281"}'::jsonb
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v WHERE truss.valid_flat_cell(v.value->'value') IS NOT TRUE)
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v
    CROSS JOIN LATERAL jsonb_array_elements(CASE v.value->'value'->>'kind' WHEN 'sequence' THEN v.value->'value'->'items' WHEN 'map' THEN v.value->'value'->'entries' ELSE '[]'::jsonb END) child
    WHERE truss.valid_scalar_cell(CASE v.value->'value'->>'kind' WHEN 'map' THEN child.value->'value' ELSE child.value END) IS NOT TRUE)) IS TRUE)
  AND NOT ((record->'payloadProfile'='{"identity":"truss-scalar-import-payload","version":"0.1","sha256":"bc7624102bf13a1f87d5382be8d7d02007c49f1775dbca14489a650d7d7ec2ed"}'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(value->'values') v WHERE truss.valid_scalar_cell(v.value->'value') IS NOT TRUE)) IS TRUE)) OR encode(sha256(payload),'hex') IS DISTINCT FROM record->'payload'->>'sha256'
  OR octet_length(payload) NOT BETWEEN 1 AND 1048576 OR (convert_from(payload,'UTF8') IS JSON OBJECT WITH UNIQUE KEYS) IS NOT TRUE THEN RAISE EXCEPTION 'exact original profiled payload required' USING ERRCODE='22023';END IF;
 IF owned_selection AND owned_profile_matches IS NOT TRUE THEN RAISE EXCEPTION 'owned import group profile required' USING ERRCODE='0A000';END IF;
 IF value-ARRAY['interfaceVersion','kind','values','source',CASE record->>'kind' WHEN 'object' THEN 'ownership' ELSE 'orderKey' END]<>'{}'::jsonb THEN RAISE EXCEPTION 'closed profiled import payload required' USING ERRCODE='22023';END IF;
 IF (record->>'kind' IN ('object','edge')) IS NOT TRUE OR value->>'interfaceVersion' IS DISTINCT FROM (CASE WHEN owned_selection THEN 'truss-owned-import-payload/0.1.0' ELSE 'truss-import-payload/0.1.0' END) OR value->>'kind' IS DISTINCT FROM record->>'kind' OR result->>'outcome'<>'created'
  OR load_id_asserted IS NOT TRUE THEN
  RAISE EXCEPTION 'original import creation/load origin required' USING ERRCODE='22023';END IF;
 IF record->>'kind'='object' THEN
  kind:='o';
  IF operation->>'operation'<>'create_object' OR operation->>'typeDefinitionPin' IS DISTINCT FROM record->'identity'->'type'->>'definitionPin'
   OR operation->'values' IS DISTINCT FROM value->'values' OR NOT owned_selection AND operation->'ownership' IS DISTINCT FROM value->'ownership' THEN RAISE EXCEPTION 'original object payload creation required' USING ERRCODE='22023';END IF;
  SELECT * INTO STRICT selected_type FROM truss.type_def WHERE type_id=(result->'identity'->>'typeId')::int;
  metadata:=convert_from(truss.import_key_selection(selected_type.document_id,selected_type.module,selected_type.element,
   (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation())),'UTF8')::jsonb;
  IF (record->'identity')-ARRAY['operation','type','keyNumber','keyDefinitionPin','keyEncodingProfile','components']<>'{}'::jsonb OR record->'identity'->>'operation' IS DISTINCT FROM 'object_key' OR jsonb_typeof(record->'identity'->'components') IS DISTINCT FROM 'array' OR record->'identity'->'type' IS DISTINCT FROM metadata->'type' OR record->'identity'->>'keyNumber' IS DISTINCT FROM metadata->>'keyNumber'
   OR record->'identity'->>'keyDefinitionPin' IS DISTINCT FROM metadata->>'keyDefinitionPin' OR (record->'identity'->'keyEncodingProfile' IS DISTINCT FROM metadata->'keyEncodingProfile' AND NOT ((record->'identity'->'keyEncodingProfile'='{"identity":"truss-selected-umf-string-key","version":"0.1","sha256":"07e1b99b22803e55a378f8068a6b80454b7581129c66eabcb117545746a16625"}'::jsonb AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(record->'identity'->'components') c WHERE c.value->'value'->>'kind' IS DISTINCT FROM 'string')) IS TRUE))
   OR jsonb_array_length(record->'identity'->'components') IS DISTINCT FROM jsonb_array_length(metadata->'components') THEN RAISE EXCEPTION 'actual complete import primary key required' USING ERRCODE='22023';END IF;
  WITH value_rows AS MATERIALIZED (
   SELECT v.value AS authored_value,v.ordinality
   FROM jsonb_array_elements(value->'values') WITH ORDINALITY v(value,ordinality)
  ), values_by_name AS MATERIALIZED (
   SELECT jsonb_object_agg(authored_value->>'name',authored_value->'value')
    FILTER(WHERE jsonb_typeof(authored_value->'name')='string') AS value_map FROM value_rows
  ), components AS MATERIALIZED (
   SELECT c.value AS component,c.ordinality,
    metadata->'components'->((c.ordinality-1)::int) AS metadata_field
   FROM jsonb_array_elements(record->'identity'->'components') WITH ORDINALITY c(value,ordinality)
  ), component_checks AS (
   SELECT (component-ARRAY['propertyId','definitionPin','value']<>'{}'::jsonb
    OR jsonb_typeof(component->'propertyId') IS DISTINCT FROM 'string'
    OR jsonb_typeof(component->'definitionPin') IS DISTINCT FROM 'string'
    OR truss.valid_scalar_cell(component->'value',NULL,false) IS NOT TRUE
    OR component->>'propertyId' IS DISTINCT FROM metadata_field->>'propertyId'
    OR component->>'definitionPin' IS DISTINCT FROM metadata_field->>'definitionPin'
    OR value_map->(metadata_field->>'name') IS DISTINCT FROM component->'value') AS invalid
   FROM components CROSS JOIN values_by_name
  )
  SELECT coalesce(bool_or(invalid),false)
    OR (SELECT count(*)<>count(DISTINCT authored_value->>'name') FROM value_rows)
   INTO component_invalid FROM component_checks;
  IF component_invalid THEN RAISE EXCEPTION 'original primary field/payload agreement required' USING ERRCODE='22023';END IF;
 ELSE
  kind:='e';
  IF operation->>'operation'<>'create_edge' OR operation->>'relationshipDefinitionPin' IS DISTINCT FROM record->'identity'->>'relationshipDefinitionPin'
   OR NOT owned_selection AND (operation->'source' IS DISTINCT FROM jsonb_build_object('state','stored','identity',record->'identity'->'source') OR operation->'target' IS DISTINCT FROM jsonb_build_object('state','stored','identity',record->'identity'->'target'))
   OR operation->'values' IS DISTINCT FROM value->'values' OR operation->'orderKey' IS DISTINCT FROM value->'orderKey' THEN RAISE EXCEPTION 'original edge payload creation required' USING ERRCODE='22023';END IF;
 END IF;
 -- The granted source-registration facade enforces the same selected import
 -- subset itself; calling the Python identity preflight is not authority.
 IF owned_selection THEN
  IF kind='o' THEN
   IF value->'ownership'='{"state":"rootless"}'::jsonb THEN root_identity:=NULL;
   ELSIF value->'ownership'->>'state'='owned' AND (value->'ownership')-ARRAY['state','root']='{}'::jsonb THEN
    root_identity:=truss.runtime_owned_import_reference(convert_to((value->'ownership'->'root')::text,'UTF8'),
     (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
    root_identity:=nullif(root_identity,'null'::jsonb);
    IF root_identity IS NULL THEN RAISE EXCEPTION 'live imported aggregate root required' USING ERRCODE='22023';END IF;
   ELSE RAISE EXCEPTION 'explicit original imported ownership required' USING ERRCODE='22023';END IF;
   IF operation->'ownership'->>'state' IS DISTINCT FROM value->'ownership'->>'state' OR NOT EXISTS(
    SELECT 1 FROM truss.object o WHERE o.id=(result->'identity'->>'id')::bigint AND o.type_id=(result->'identity'->>'typeId')::int
     AND o.root_id IS NOT DISTINCT FROM (root_identity->>'id')::bigint
     AND o.root_type IS NOT DISTINCT FROM (root_identity->>'typeId')::int) THEN
    RAISE EXCEPTION 'original imported ownership correspondence required' USING ERRCODE='55000';END IF;
  ELSE
   resolved_source_identity:=truss.runtime_owned_import_reference(convert_to((record->'identity'->'source')::text,'UTF8'),
    (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
   resolved_target_identity:=truss.runtime_owned_import_reference(convert_to((record->'identity'->'target')::text,'UTF8'),
    (SELECT release_id FROM truss.runtime_current_installation()),(SELECT release_sha256 FROM truss.runtime_current_installation()))->'identity';
   resolved_source_identity:=nullif(resolved_source_identity,'null'::jsonb);resolved_target_identity:=nullif(resolved_target_identity,'null'::jsonb);
   IF resolved_source_identity IS NULL OR resolved_target_identity IS NULL OR NOT EXISTS(
    SELECT 1 FROM truss.runtime_edge_transition t WHERE t.attempt_id=selected_attempt AND t.operation_index=selected_index
     AND t.before_edge IS NULL AND t.edge_id=(result->'identity'->>'id')::bigint AND t.rel_type_id=(result->'identity'->>'typeId')::int
     AND t.source_identity IS NOT DISTINCT FROM resolved_source_identity AND t.target_identity IS NOT DISTINCT FROM resolved_target_identity) THEN
    RAISE EXCEPTION 'original imported endpoint correspondence required' USING ERRCODE='55000';END IF;
  END IF;
 ELSIF kind='o' THEN
  IF operation->'ownership' IS DISTINCT FROM '{"state":"rootless"}'::jsonb OR NOT EXISTS(
   SELECT 1 FROM truss.object o WHERE o.id=(result->'identity'->>'id')::bigint AND o.type_id=(result->'identity'->>'typeId')::int
    AND o.root_id IS NULL AND o.root_type IS NULL) THEN
   RAISE EXCEPTION 'original rootless object source profile required' USING ERRCODE='0A000';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM truss.edge e JOIN truss.rel_def r ON r.rel_type_id=e.rel_type_id
   JOIN truss.object source_object ON source_object.id=e.source_id AND source_object.type_id=e.source_type
   JOIN truss.object target_object ON target_object.id=e.target_id AND target_object.type_id=e.target_type
   WHERE e.id=(result->'identity'->>'id')::bigint AND e.rel_type_id=(result->'identity'->>'typeId')::int
    AND r.lifecycle='independent' AND source_object.root_id IS NULL AND source_object.root_type IS NULL
    AND target_object.root_id IS NULL AND target_object.root_type IS NULL)
   OR NOT EXISTS(SELECT 1 FROM truss.runtime_edge_transition t WHERE t.attempt_id=selected_attempt AND t.operation_index=0
    AND t.edge_id=(result->'identity'->>'id')::bigint AND t.rel_type_id=(result->'identity'->>'typeId')::int
    AND t.before_edge IS NULL AND t.endpoint_ownership->'after'->'source'->'ownership'='{"state":"rootless"}'::jsonb
    AND t.endpoint_ownership->'after'->'target'->'ownership'='{"state":"rootless"}'::jsonb) THEN
   RAISE EXCEPTION 'original rootless independent edge source profile required' USING ERRCODE='0A000';END IF;
 END IF;
 IF value ? 'source' THEN
  IF (value->'source')-ARRAY['kind','entries']<>'{}'::jsonb OR value->'source'->>'kind' IS DISTINCT FROM 'map' OR jsonb_typeof(value->'source'->'entries') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'exact source map required' USING ERRCODE='22023';END IF;
  WITH source_entries AS MATERIALIZED (
   SELECT e.value AS source_entry,e.ordinal
   FROM jsonb_array_elements(value->'source'->'entries') WITH ORDINALITY e(value,ordinal)
  ), projected AS (
   SELECT se.source_entry,se.ordinal,se.source_entry->>'key' AS source_key,
    CASE se.source_entry->'value'->>'kind' WHEN 'string' THEN se.source_entry->'value'->'text' WHEN 'null' THEN 'null'::jsonb WHEN 'boolean' THEN se.source_entry->'value'->'value' ELSE se.source_entry->'value' END AS cell_source_value,
    (se.source_entry-ARRAY['key','value']<>'{}'::jsonb OR jsonb_typeof(se.source_entry->'key') IS DISTINCT FROM 'string'
     OR octet_length(se.source_entry->>'key') NOT BETWEEN 1 AND 4096 OR truss.valid_scalar_cell(se.source_entry->'value') IS NOT TRUE
     OR se.source_entry->>'key' IN ('author','at','system') AND se.source_entry->'value'->>'kind' NOT IN ('string','null')) AS invalid
   FROM source_entries se
  )
  SELECT coalesce(bool_or(projected.invalid),false) OR count(projected.source_key)<>count(DISTINCT projected.source_key),
   coalesce(jsonb_object_agg(projected.source_key,projected.cell_source_value ORDER BY projected.ordinal)
    FILTER(WHERE projected.source_key IS NOT NULL),'{}'::jsonb)
   INTO source_invalid,source_value FROM projected;
  IF source_invalid THEN RAISE EXCEPTION 'lossless unique scalar source facts required' USING ERRCODE='22023';END IF;
 END IF;
 source_entity_id:=(result->'identity'->>'id')::bigint;
 INSERT INTO truss.record_source(entity_kind,entity_id,load_id,source) VALUES(kind,source_entity_id,load_id,source_value) RETURNING * INTO source_row;
 GET DIAGNOSTICS inserted_rows=ROW_COUNT;
 IF inserted_rows<>1 THEN RAISE EXCEPTION 'one imported source row required' USING ERRCODE='55000';END IF;
 expected_source:=to_jsonb(source_row);
 -- Preserve imported_at in the scalar result; the immutable row is the
 -- canonical source fact, so the compatibility ledger column stays empty.
 INSERT INTO truss.runtime_import_source(entity_kind,entity_id,group_attempt_id,writer_xid,original_record,expected_source,operation_index)
 VALUES(kind,source_entity_id,selected_attempt,checked_writer_xid,original_record,'{}'::jsonb,selected_index);
 PERFORM truss.runtime_module_writer(result->'identity'->'owner'->>'documentId',result->'identity'->'owner'->>'moduleId');
 RETURN convert_to(expected_source::text,'UTF8');
END;
$function$
CREATE OR REPLACE FUNCTION truss.runtime_person(require_registrar boolean)
 RETURNS oid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor record; installation truss.catalog_runtime_installation%ROWTYPE;
 member_of_owner boolean; member_of_registrar boolean; member_of_server_capability boolean; unsafe_switchable boolean;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'catalog authorization requires READ COMMITTED' USING ERRCODE='0A000'; END IF;
 SELECT * INTO STRICT installation FROM truss.runtime_current_installation();
 IF current_setting('truss.runtime_digest',true) IS DISTINCT FROM installation.release_sha256 THEN
  RAISE EXCEPTION 'latest runtime required; explicitly migrate the installation' USING ERRCODE='0A000'; END IF;
 SELECT oid,rolcanlogin,rolsuper,rolcreaterole,rolcreatedb,rolreplication,rolbypassrls INTO STRICT actor
 FROM pg_roles WHERE rolname=session_user;
 -- Read membership rows under the current snapshot instead of a role cache
 -- populated while executing a nested SECURITY DEFINER wrapper.
 WITH RECURSIVE memberships(role_oid) AS (
  SELECT actor.oid UNION
  SELECT m.roleid FROM pg_auth_members m JOIN memberships p ON m.member=p.role_oid
 ) SELECT coalesce(bool_or(role_oid=installation.owner_oid),false),
          coalesce(bool_or(role_oid=installation.registrar_oid),false),
          coalesce(bool_or(role_oid IN (SELECT oid FROM pg_roles WHERE rolname IN
           ('pg_read_server_files','pg_write_server_files','pg_execute_server_program'))),false)
 INTO member_of_owner,member_of_registrar,member_of_server_capability FROM memberships;
 WITH RECURSIVE role_states(active_oid,privilege_oid) AS (
  SELECT actor.oid,actor.oid UNION
  SELECT CASE WHEN m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid)
              THEN m.roleid ELSE s.active_oid END,m.roleid
  FROM pg_auth_members m JOIN role_states s ON m.member=s.privilege_oid
  WHERE m.inherit_option OR m.admin_option OR (m.set_option AND s.active_oid=s.privilege_oid)
 ) SELECT EXISTS(SELECT 1 FROM (SELECT DISTINCT active_oid FROM role_states) s JOIN pg_roles r ON r.oid=s.active_oid
   WHERE r.rolsuper OR r.rolcreaterole OR r.rolcreatedb OR r.rolreplication OR r.rolbypassrls
    OR CASE WHEN s.active_oid=actor.oid THEN false ELSE (has_schema_privilege(r.oid,'truss','CREATE')
    OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss'
      AND ((c.relkind IN ('r','p') AND (has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
        OR has_any_column_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')))
       OR (c.relkind='S' AND has_sequence_privilege(r.oid,c.oid,'USAGE,SELECT,UPDATE'))))) END) INTO unsafe_switchable;
 IF current_setting('server_version_num')<>'180006' OR current_setting('role')<>'none' OR NOT actor.rolcanlogin OR actor.rolsuper
  OR actor.rolcreaterole OR actor.rolcreatedb OR actor.rolreplication OR actor.rolbypassrls
  OR actor.oid=installation.owner_oid OR member_of_owner OR member_of_server_capability OR unsafe_switchable
  OR NOT EXISTS(SELECT 1 FROM pg_namespace n JOIN pg_roles r ON r.oid=n.nspowner
   WHERE n.nspname='truss' AND r.oid=installation.owner_oid AND NOT r.rolcanlogin AND NOT r.rolsuper
    AND NOT r.rolcreaterole AND NOT r.rolcreatedb AND NOT r.rolreplication AND NOT r.rolbypassrls AND NOT r.rolinherit)
  OR has_schema_privilege(actor.oid,'truss','CREATE')
  OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='truss'
    AND ((c.relkind IN ('r','p') AND (has_table_privilege(actor.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN')
      OR has_any_column_privilege(actor.oid,c.oid,'SELECT,INSERT,UPDATE,REFERENCES')))
     OR (c.relkind='S' AND has_sequence_privilege(actor.oid,c.oid,'USAGE,SELECT,UPDATE'))))
  OR (SELECT oid FROM pg_roles WHERE rolname=current_user) IS DISTINCT FROM installation.owner_oid
  OR require_registrar IS NULL OR (require_registrar AND NOT member_of_registrar) THEN
  RAISE EXCEPTION 'catalog registration authorization required' USING ERRCODE='42501'; END IF;
 RETURN actor.oid;
END;
$function$
